import{F as e,W as t,_ as n,f as r,g as i,h as a,j as o,l as s,n as c}from"./chunks/shared.rYHlazZf.js";var l=JSON.parse(`{"title":"Prepare overlays para o OBS","description":"","frontmatter":{"title":"Prepare overlays para o OBS","docId":"user.overlays.index","translationKey":"user.overlays.index","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3141f778f3bf0e5c9e01415122e7863e9342c266a57bee9811d7a6b75b2c842b","translationRevision":"13421eb11b0523733e2dbe6c14b6ee186fc2602ea88fd79320980121ee0abf29","order":10},"headers":[],"relativePath":"pt/user/overlays/index.md","filePath":"pt/user/overlays/index.md","lastUpdated":1795735295000}`),u={name:`pt/user/overlays/index.md`};function d(c,l,u,d,f,p){let m=e(`DemoFrame`),h=e(`DocSteps`),g=e(`DocCallout`);return o(),r(`div`,null,[l[2]||=a(`<h1 id="prepare-overlays-for-obs" tabindex="-1">Prepare overlays para o OBS <a class="header-anchor" href="#prepare-overlays-for-obs" aria-label="Permalink to “Prepare overlays para o OBS”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Projete um widget legível e conecte sua fonte de navegador local ao OBS. Você precisa do TikTools em execução, da capacidade de gateway de overlays e do OBS no mesmo computador para o endereço de loopback padrão. A saída ao vivo também precisa do evento recebido relevante ou de uma fonte de ranking configurada.</p><h2 id="design-and-preview" tabindex="-1">Projete e visualize <a class="header-anchor" href="#design-and-preview" aria-label="Permalink to “Projete e visualize”">​</a></h2>`,4),n(m,{scenario:`overlays`,locale:`pt`,panel:`overlays`,title:`Experimente o editor de sobreposições`}),n(h,null,{default:t(()=>[...l[0]||=[s(`ol`,null,[s(`li`,null,[i(`Abra `),s(`strong`,null,`Sobreposições`),i(` e leia o status do gateway. Escolha novos seguidores, presentes, chat, compartilhamentos, assinaturas, curtidas ou ranking.`)]),s(`li`,null,`Edite camadas, texto visível, cores, espaçamento e opções de avatar no inspetor de design. Use contraste suficiente e tamanho legível na resolução real da transmissão.`),s(`li`,null,`Reproduza a prévia para inspecionar o layout. O conteúdo da prévia ajuda a avaliar o design; não comprova a entrega de eventos da LIVE.`),s(`li`,null,[i(`Use os controles `),s(`strong`,null,`Desfazer/Refazer`),i(` para edições locais e depois `),s(`strong`,null,`Salvar design`),i(`. Trocar o tipo de widget com alterações não salvas solicita que você as descarte.`)]),s(`li`,null,`No painel de prévia/fonte, copie a URL da fonte. A URL exibida mascara sua credencial; use o controle de cópia para obter a URL utilizável. Mantenha essa URL privada.`),s(`li`,null,`Adicione uma fonte de navegador no OBS e cole a URL copiada. Mantenha o TikTools em execução e valide um evento relevante antes de depender dele durante uma transmissão.`)],-1)]]),_:1}),l[3]||=a(`<p>O gateway padrão é <code>127.0.0.1:17452</code>. Uma URL de loopback se refere ao computador que executa a fonte de navegador, portanto copiá-la para outro computador não alcança esse host automaticamente. Widgets de ranking também precisam de um ID de ranking selecionado; consulte o <a href="./../points/rankings.html">status dos rankings</a>.</p><h2 id="use-the-cloud-library" tabindex="-1">Use a biblioteca do Cloud <a class="header-anchor" href="#use-the-cloud-library" aria-label="Permalink to “Use a biblioteca do Cloud”">​</a></h2><p>Quando o host expuser capacidades de overlays do Cloud, abra a biblioteca em <strong>Sobreposições</strong>. Navegue por designs locais ou <strong>Meus overlays</strong>, use o editor para criar um overlay do Cloud ou abra um ID existente e revise-o. O editor do Cloud aceita texto, campos ao vivo, imagens e dimensões de tela; envios de imagens usam seu fluxo separado. Salvar o design local e criar/revisar no Cloud são operações distintas.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>Designs locais, controles de gateway e fluxos do editor/biblioteca do Cloud condicionados às capacidades estão disponíveis. Um adaptador compartilhado <strong>Changes</strong> de overlays não está disponível nesta versão. OBS, LIVE real e cada sistema operacional ainda exigem aceitação no seu ambiente.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Para saída ausente, verifique estado do gateway, recursos, credenciais, URL da fonte e tipo de evento selecionado. Para um conflito de revisão no Cloud, recarregue a revisão atual antes de editar novamente. Nunca publique o token da fonte em capturas de tela; informe o erro do gateway pelos <a href="./../preferences/troubleshooting.html">diagnósticos</a>.</p>`,7),n(g,{title:`Da prévia para a transmissão`,tone:`info`},{default:t(()=>[...l[1]||=[s(`p`,null,`A demonstração permite explorar o design sem abrir o OBS. No seu computador, copie a URL com o controle da aplicação e valide um evento na fonte de navegador escolhida. A prévia local sozinha não confirma a entrega ao OBS.`,-1)]]),_:1}),l[4]||=s(`h2`,{id:`operational-details`,tabindex:`-1`},[i(`Detalhes de operação `),s(`a`,{class:`header-anchor`,href:`#operational-details`,"aria-label":`Permalink to “Detalhes de operação”`},`​`)],-1),l[5]||=s(`p`,null,`Instale Event Gateway separadamente, habilite e confira execução antes das fontes OBS LIVE. Estados: missing → instalar; disabled → habilitar/conferir disponibilidade; stopped → iniciar; credentialUnavailable → reiniciar gateway uma vez; assetsMissing → reparar/reconstruir assets empacotados; starting → aguardar brevemente; unreachable → conferir porta/serviço loopback. Use credencial de widget da URL gerada. Ready ou prévia local não provam LIVE nem recepção OBS: confira com teste inofensivo na fonte pretendida.`,-1)])}var f=c(u,[[`render`,d]]);export{l as __pageData,f as default};